import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

// Festival Hub demo: a second, fully separate build of festival-hub/index.html.
// Runs after the calendar build (see package.json "build"), so:
//   - it shares no chunks with the calendar bundle,
//   - its files land in dist/festival-hub/ and are NOT in the calendar
//     service worker's precache (that list is generated by the first build),
//   - it has no PWA plugin and registers no service worker.
export default defineConfig({
  plugins: [react()],
  publicDir: false, // /brand, /favicon.ico etc. come from the calendar build
  build: {
    outDir: 'dist',
    emptyOutDir: false, // keep the calendar build that ran first
    assetsDir: 'festival-hub/assets',
    rollupOptions: {
      input: 'festival-hub/index.html',
    },
  },
})
